export default JSON.parse("{\"3.2.1\":{\"unit\":\"3.2\",\"courseId\":\"3.2.1\",\"hook\":{\"prompt\":\"You buy 1 lot of an FX pair on a retail platform. Who sold it to you?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"retail\",\"label\":\"Another retail trader\",\"feedback\":\"Spot FX has no central book where your order could meet another trader's. A dealer takes the other side.\"},{\"id\":\"dealer\",\"label\":\"Your broker or its liquidity provider\"},{\"id\":\"cb\",\"label\":\"The central bank\",\"feedback\":\"Central banks trade FX for policy, not to fill retail orders.\"},{\"id\":\"exchange\",\"label\":\"The exchange\",\"feedback\":\"Spot FX doesn't trade on an exchange. It's traded over the counter, with dealers.\"}],\"answer\":\"dealer\"},\"compare\":\"You said {yours}. Spot FX is a dealer market, traded over the counter: your broker, or the firm that quotes it prices, took the other side.\",\"concept\":\"market-venue-types\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"Classify spot FX\",\"text\":\"Orders meet in a [[clob|central limit order book]], against a [[dealer-market|dealer]], through a broker, or in a mix of these. Walk retail spot FX through the questions.\",\"figure\":{\"kind\":\"flow\",\"start\":\"n1\",\"interactive\":true,\"nodes\":[{\"id\":\"n1\",\"text\":\"Does your order rest in one shared book that every trader sees?\",\"kind\":\"question\",\"yes\":\"n2\",\"no\":\"n3\",\"correct\":\"no\",\"explain\":\"Retail FX orders go to your broker's price stream. Spot FX has no central book.\"},{\"id\":\"n2\",\"text\":\"Do designated market makers also quote, with obligations?\",\"kind\":\"question\",\"yes\":\"hybrid\",\"no\":\"clob\"},{\"id\":\"n3\",\"text\":\"Do you trade at prices a dealer quotes to you?\",\"kind\":\"question\",\"yes\":\"dealer\",\"no\":\"brokered\",\"correct\":\"yes\",\"explain\":\"Your broker, or the liquidity provider behind it, quotes the bid and ask, and you trade against them.\"},{\"id\":\"hybrid\",\"text\":\"Hybrid: a central book plus market makers with obligations\",\"kind\":\"end\"},{\"id\":\"clob\",\"text\":\"Order-driven: a central limit order book\",\"kind\":\"end\"},{\"id\":\"dealer\",\"text\":\"Quote-driven: a dealer market\",\"kind\":\"end\"},{\"id\":\"brokered\",\"text\":\"Brokered: a broker searches for the other side\",\"kind\":\"end\"}],\"steps\":[\"Order-driven: one shared book; orders match by price, then by time.\",\"Quote-driven: dealers quote a bid and an ask, and you trade against them.\",\"Brokered: a broker finds the other side, usually for large blocks.\",\"Hybrid: a central book plus market makers with quoting obligations. Retail spot FX is quote-driven.\"]},\"concept\":\"market-venue-types\"},{\"kind\":\"match\",\"title\":\"Name the structure\",\"prompt\":\"Match each market to the way its orders meet.\",\"pairs\":[{\"left\":\"A stock exchange's continuous session\",\"right\":\"Order-driven\",\"wrong\":\"Orders rest in the exchange's central book and match by price, then time.\"},{\"left\":\"Spot FX on a retail platform\",\"right\":\"Quote-driven\",\"wrong\":\"You trade against prices your broker or its liquidity provider quotes.\"},{\"left\":\"A corporate bond, quotes requested from five dealers\",\"right\":\"Quote-driven\",\"wrong\":\"A request for quote goes to dealers, and you trade with the best of them.\"},{\"left\":\"500,000 shares in one block, matched by a broker\",\"right\":\"Brokered\",\"wrong\":\"Blocks this large are usually matched by a broker who searches for the other side.\"},{\"left\":\"NYSE: a central book plus a designated market maker\",\"right\":\"Hybrid\",\"wrong\":\"The book is central, and the designated market maker has quoting obligations: a hybrid.\"}],\"columns\":[\"Market\",\"Structure\"],\"correct\":\"Bonds and FX are mostly dealer markets, stocks trade in central books, blocks go through brokers, and many exchanges mix a book with market makers.\",\"concept\":\"market-venue-types\"},{\"kind\":\"explain\",\"title\":\"One instrument, many venues\",\"text\":\"A [[venue]] is any place where orders meet. US stocks trade on more than a dozen exchanges, in [[dark-pool|dark pools]] and at firms that [[internalisation|internalise]] orders; over a third of volume trades off-exchange. Spot FX is an [[otc-market|over-the-counter market]]: about 9.6 trillion dollars a day (BIS, April 2025), with no central book. Grade: Mechanic.\"},{\"kind\":\"hotspot\",\"title\":\"Two books, one stock\",\"prompt\":\"LABX trades on two venues, and your broker's screen shows only venue A. Tap the better ask for a buyer.\",\"chart\":{\"candles\":[{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01},{\"o\":100.01,\"h\":100.01,\"l\":100.01,\"c\":100.01}],\"hideCandles\":true,\"range\":[99.91,100.11],\"height\":280,\"layers\":[{\"kind\":\"level\",\"price\":100.07,\"role\":\"resistance\",\"label\":\"VENUE A ASK 100.07\",\"chip\":false},{\"kind\":\"level\",\"price\":100.05,\"role\":\"resistance\",\"label\":\"VENUE B ASK 100.05\",\"chip\":false},{\"kind\":\"level\",\"price\":99.97,\"role\":\"support\",\"label\":\"VENUE A BID 99.97\",\"chip\":false},{\"kind\":\"level\",\"price\":99.95,\"role\":\"support\",\"label\":\"VENUE B BID 99.95\",\"chip\":false}],\"describe\":\"Two venues quote LABX. Venue A: bid 99.97, ask 100.07. Venue B: bid 99.95, ask 100.05.\"},\"zones\":[{\"id\":\"a-ask\",\"label\":\"Venue A ask 100.07\",\"price\":100.07,\"feedback\":\"That's the ask your broker shows. Venue B offers the same thing 0.02 cheaper.\"},{\"id\":\"b-ask\",\"label\":\"Venue B ask 100.05\",\"price\":100.05},{\"id\":\"a-bid\",\"label\":\"Venue A bid 99.97\",\"price\":99.97,\"feedback\":\"That's a bid: where you could sell. A buyer pays an ask.\"},{\"id\":\"b-bid\",\"label\":\"Venue B bid 99.95\",\"price\":99.95,\"feedback\":\"That's a bid: where you could sell. A buyer pays an ask.\"}],\"answer\":\"b-ask\",\"correct\":\"Right: 100.05 on B. Put together, the best prices are 99.97 / 100.05, a 0.08 spread, tighter than either venue alone.\",\"concept\":\"venue-fragmentation\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"Your broker's chart is one price stream, not the market. In spot FX and CFDs its volume bars are [[tick-volume]]: price changes counted at that broker, not units traded.\"},{\"kind\":\"worked\",\"title\":\"Your turn: split the order\",\"lines\":[\"Buy 300 LABX. Venue A asks: 100 at 100.07, 200 at 100.08. Venue B asks: 150 at 100.05, 100 at 100.09.\",\"Cheapest first: 150 at 100.05 on B, 100 at 100.07 on A, 50 at 100.08 on A.\",\"Split cost: 15,007.50 + 10,007.00 + 5,004.00 = 30,018.50.\",\"All on A: 10,007.00 + 20,016.00 = 30,023.00.\",\"Saved by splitting = ?\"],\"ask\":{\"answer\":4.5,\"tolerance\":0.005,\"unit\":\"vUSD\",\"feedback\":[{\"value\":30018.5,\"text\":\"That's the split's total cost. Subtract it from the cost on A alone.\"},{\"value\":3,\"text\":\"That's only the first 150 units, 0.02 each. Compare the two full totals.\"}],\"correct\":\"Right: 4.50 saved, 30,023.00 − 30,018.50.\"},\"after\":\"That's what a router does: it takes the cheapest levels across venues. Venue B alone couldn't fill 300 units: it shows only 250.\",\"concept\":\"venue-fragmentation\"},{\"kind\":\"match\",\"title\":\"Who is on the other side?\",\"prompt\":\"Match each account to your [[counterparty]] when you buy.\",\"pairs\":[{\"left\":\"Shares on an exchange\",\"right\":\"Another trader whose order matched yours\",\"wrong\":\"Your order meets another participant's order in the book; a clearing house then stands between you.\"},{\"left\":\"Spot FX with a dealer broker\",\"right\":\"The dealer: your broker or its liquidity provider\",\"wrong\":\"A dealer quotes the price and takes the other side itself.\"},{\"left\":\"A CFD on an index\",\"right\":\"The CFD provider\",\"wrong\":\"A [[cfd|CFD]] is a contract with its provider. It may hedge, but it is your counterparty.\"}],\"columns\":[\"Account\",\"Counterparty\"],\"correct\":\"Exchange: another trader. Dealer FX: the dealer. CFD: the provider, always. Knowing who is on the other side tells you whose interests meet yours.\",\"concept\":\"market-venue-types\"}],\"check\":[\"q-3.2.1-1\",\"q-3.2.1-2\",\"q-3.2.1-3\"],\"recap\":{\"takeaways\":[\"Orders meet in a central book, against a dealer, through a broker, or in a hybrid.\",\"Spot FX and CFDs have no central book; their volume is tick volume at one broker.\",\"Counterparty: another trader on an exchange, the dealer in FX, the provider in a CFD.\"]}},\"3.2.2\":{\"unit\":\"3.2\",\"courseId\":\"3.2.2\",\"hook\":{\"prompt\":\"Your 500-unit market buy walked 3 ticks into the book. Before a release, liquidity providers pull 70% of the depth. How many ticks does the same order walk now?\",\"control\":{\"kind\":\"slider\",\"min\":1,\"max\":20,\"step\":1,\"unit\":\"ticks\",\"start\":3,\"answer\":12,\"tolerance\":0,\"feedback\":[{\"from\":1,\"to\":4,\"text\":\"That's about the old walk. With only 30% of each level left, 500 units need many more levels.\"},{\"from\":5,\"to\":9,\"text\":\"Further than before, but not enough: the first six levels now hold only 426 units.\"},{\"from\":10,\"to\":11,\"text\":\"Close. Count the remaining sizes until you reach 500: the order reaches the seventh level.\"},{\"from\":12,\"to\":12,\"text\":\"Right: 12 ticks, from 100.05 to 100.17.\"},{\"from\":13,\"to\":20,\"text\":\"Too far: 546 units remain up to 100.17, enough for 500.\"}]},\"compare\":\"You said {yours}. With 70% of the depth gone, the same 500 units walked 12 ticks, to 100.17, instead of 3.\",\"concept\":\"market-depth\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"The book, level by level\",\"text\":\"[[level-1|L1]] shows the best bid and ask with their sizes. [[level-2|L2]] adds the size at every price. Add the sizes up from the best price and you get the [[depth-chart|depth curve]]. [[level-3|L3]] shows every single order and its place in the queue.\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Bid 99.95\",\"value\":150,\"role\":\"accent\"},{\"label\":\"Ask 100.05\",\"value\":120,\"role\":\"neutral\"},{\"label\":\"Ask 100.06\",\"value\":200,\"role\":\"neutral\"},{\"label\":\"Ask 100.08\",\"value\":300,\"role\":\"neutral\"},{\"label\":\"Ask 100.10\",\"value\":250,\"role\":\"neutral\"},{\"label\":\"Ask 100.12\",\"value\":250,\"role\":\"neutral\"},{\"label\":\"Ask 100.15\",\"value\":300,\"role\":\"neutral\"},{\"label\":\"Ask 100.17\",\"value\":400,\"role\":\"neutral\"}],\"unit\":\" units\",\"steps\":[\"L1: best bid 99.95 for 150 units, best ask 100.05 for 120.\",\"L2: 200 more at 100.06 and 300 at 100.08.\",\"Depth: 1,120 units offered within 7 ticks of the best ask.\",\"In all, 1,820 units within 12 ticks. L3 would split each bar into single orders.\"]},\"concept\":\"limit-order-book\"},{\"kind\":\"worked\",\"title\":\"Walk the book\",\"lines\":[\"A market buy of 500 units meets the asks above.\",\"It takes 120 at 100.05, 200 at 100.06 and the last 180 at 100.08.\",\"Cost: 12,006.00 + 20,012.00 + 18,014.40 = 50,032.40.\",\"Average fill price = 50,032.40 ÷ 500 = ?\"],\"ask\":{\"answer\":100.0648,\"tolerance\":0.005,\"unit\":\"vUSD\",\"feedback\":[{\"value\":100.05,\"text\":\"That's the best ask. Only the first 120 units got it.\"},{\"value\":100.08,\"text\":\"That's the last level reached. Average over all 500 units.\"}],\"correct\":\"Right: about 100.06 (100.0648).\"},\"after\":\"That's [[walking-the-book|walking the book]]. Against the best ask, the [[slippage]] is (100.0648 − 100.05) × 500 = 7.40 vUSD.\",\"concept\":\"market-depth\"},{\"kind\":\"match\",\"title\":\"Four ways to be liquid\",\"prompt\":\"Match each dimension of [[liquidity]] to how you would measure it.\",\"pairs\":[{\"left\":\"Tightness\",\"right\":\"The bid-ask spread\",\"wrong\":\"Tightness is how close the best bid and ask are: the spread.\"},{\"left\":\"Depth\",\"right\":\"Units offered within a few ticks\",\"wrong\":\"Depth is the size near the best prices.\"},{\"left\":\"Resiliency\",\"right\":\"Time for the book to refill after a sweep\",\"wrong\":\"Resiliency is how fast size comes back after a large order uses it up.\"},{\"left\":\"Immediacy\",\"right\":\"How long an order takes to execute\",\"wrong\":\"Immediacy is speed: how soon you can trade at all.\"}],\"columns\":[\"Dimension\",\"Measure\"],\"correct\":\"A market can be tight but thin, or deep but slow to refill. Check all four before a large order, [[resiliency]] included.\",\"concept\":\"liquidity-dimensions\"},{\"kind\":\"predict\",\"title\":\"The depth shock\",\"prompt\":\"Before a release, each level keeps only 30%: 36, 60, 90, 75, 75, 90 and 120 units. Your same 500-unit buy: how does its slippage compare with the 7.40 before?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"same\",\"label\":\"About the same\",\"feedback\":\"The best ask didn't move, but the sizes behind it shrank. The order has to reach much further.\"},{\"id\":\"twice\",\"label\":\"About twice as much\",\"feedback\":\"More than that: the order now reaches the seventh level, 100.17.\"},{\"id\":\"four\",\"label\":\"About four times as much\"},{\"id\":\"ten\",\"label\":\"About ten times as much\",\"feedback\":\"Less than that: 30.18 against 7.40.\"}],\"answer\":\"four\"},\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Calm book\",\"value\":7.4,\"role\":\"neutral\"},{\"label\":\"After the pull\",\"value\":30.18,\"role\":\"down\"}],\"unit\":\" vUSD\"},\"reveal\":\"The order now runs out of size only at 100.17: 12 ticks, average 100.1104, slippage 30.18 vUSD, about four times the 7.40. Liquidity thinning before news and in stress is documented (grade B): the depth you saw minutes ago isn't the depth you trade.\",\"concept\":\"market-depth\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"Displayed size is an intention, not a commitment: it can vanish. Placing orders you intend to cancel before they fill, to mislead others, is spoofing, and it's illegal. US regulators found one trader's layering contributed to the book imbalance before the 6 May 2010 flash crash (CFTC v. Sarao, 2016). Lesson 3.3.7 has the case.\"},{\"kind\":\"worked\",\"title\":\"Your turn: estimate before you send\",\"lines\":[\"A new book. Asks: 100 at 100.25, 150 at 100.26, 200 at 100.28, 250 at 100.30, 300 at 100.33.\",\"A market buy of 400 units takes 100 at 100.25, 150 at 100.26 and 150 at 100.28.\",\"Cost: 10,025.00 + 15,039.00 + 15,042.00 = 40,106.00.\",\"Average fill price = ?\"],\"ask\":{\"answer\":100.265,\"tolerance\":0.01,\"unit\":\"vUSD\",\"feedback\":[{\"value\":100.25,\"text\":\"That's the best ask. Only the first 100 units got it.\"},{\"value\":100.28,\"text\":\"That's the last level reached. Divide the total cost by 400.\"}],\"correct\":\"Right: 100.265, 6.00 vUSD more than 400 units at the best ask.\"},\"concept\":\"market-depth\"},{\"kind\":\"predict\",\"title\":\"Your turn: after the shock\",\"prompt\":\"Before a release, each level of that book keeps 40%: 40, 60, 80, 100 and 120 units. Estimate the average price of the same 400-unit buy.\",\"control\":{\"kind\":\"numeric\",\"unit\":\"vUSD\",\"answer\":100.294,\"tolerance\":0.01,\"feedback\":[{\"value\":100.265,\"text\":\"That's the calm book. With 40% of the size left, 400 units must reach 100.33.\"},{\"value\":100.33,\"text\":\"That's the last level reached. Weight each price by its units.\"}]},\"reveal\":\"It takes every level, up to 100.33: 4,010.00 + 6,015.60 + 8,022.40 + 10,030.00 + 12,039.60 = 40,117.60, or 100.294 a unit. Same order, 11.60 vUSD more, because the depth left.\",\"concept\":\"market-depth\"}],\"check\":[\"q-3.2.2-1\",\"q-3.2.2-2\",\"q-3.2.2-3\"],\"recap\":{\"takeaways\":[\"L1: best bid and ask. L2: size at each price. L3: every order and its queue place.\",\"Average fill = total cost ÷ units; the order walks further when depth is thin.\",\"Displayed size can vanish before news; orders meant to be cancelled are illegal spoofing.\"]}},\"3.2.3\":{\"unit\":\"3.2\",\"courseId\":\"3.2.3\",\"hook\":{\"prompt\":\"You quote 99.95 / 100.05 and earn half the spread, 0.05, on every fill. In one session you get 60 fills of 100 units. What is your session P&L?\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":600,\"step\":10,\"unit\":\"vUSD\",\"start\":150,\"answer\":60,\"tolerance\":10,\"feedback\":[{\"from\":0,\"to\":40,\"text\":\"Lower than it turned out. The spread paid 300.00; the informed fills took 240.00 of it.\"},{\"from\":50,\"to\":70,\"text\":\"Right: the spread paid 300.00, but 8 fills came just before a move against you.\"},{\"from\":80,\"to\":280,\"text\":\"Between the spread and the result. Some fills came from a trader who knew more.\"},{\"from\":290,\"to\":310,\"text\":\"That's the spread alone: 60 × 100 × 0.05. Some fills came just before price moved against you.\"},{\"from\":320,\"to\":600,\"text\":\"More than the spread can pay: 60 × 100 × 0.05 = 300.00 is the ceiling.\"}]},\"compare\":\"You said {yours}. The spread paid 300.00, but 8 fills came from an informed trader just before a 0.30 move against you: −240.00. Net: 60.00.\",\"concept\":\"market-making\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"What the spread pays for\",\"text\":\"A [[market-maker]] quotes both sides and earns the [[spread]]. Models from the 1980s (Glosten–Milgrom, Stoll) split it into three costs: processing, [[inventory-risk|inventory risk]] and [[adverse-selection|adverse selection]]. Here is an illustrative split of LABX's 0.10; real shares are estimated market by market.\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Order processing\",\"value\":0.02,\"role\":\"neutral\"},{\"label\":\"Inventory risk\",\"value\":0.03,\"role\":\"accent\"},{\"label\":\"Adverse selection\",\"value\":0.05,\"role\":\"down\"}],\"steps\":[\"Processing: systems, staff and fees, paid on every trade.\",\"Inventory: pay for holding positions the flow forces on you.\",\"Adverse selection: what traders who know more take from you.\"]},\"concept\":\"market-making\"},{\"kind\":\"worked\",\"title\":\"Split the P&L\",\"lines\":[\"Spread captured: 60 fills × 100 units × 0.05 = 300.00.\",\"Adverse selection: 8 fills came from an informed trader just before a 0.30 move against you: 8 × 100 × 0.30 = 240.00.\",\"Inventory: you ended flat, so 0.00.\",\"Net P&L before commissions = ?\"],\"ask\":{\"answer\":60,\"tolerance\":0,\"unit\":\"vUSD\",\"feedback\":[{\"value\":300,\"text\":\"That's the spread alone. Subtract what the informed fills cost.\"},{\"value\":540,\"text\":\"Adverse selection is a loss: subtract the 240.00, don't add it.\"},{\"value\":-240,\"text\":\"The spread still paid 300.00 on all 60 fills. Net the two.\"}],\"correct\":\"Right: 60.00. Eight fills out of 60 took 80% of the spread you earned.\"},\"after\":\"That's the market maker's problem in one line: everyone pays the spread, and the losses come from the few who know more.\",\"concept\":\"adverse-selection\"},{\"kind\":\"predict\",\"title\":\"Before the release\",\"prompt\":\"Informed orders tend to arrive just before a release. What do you do with your quotes?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"widen\",\"label\":\"Widen them\",\"feedback\":\"Yes, and dealers do more than that.\"},{\"id\":\"skew\",\"label\":\"Skew them\",\"feedback\":\"Yes, if you hold inventory, and dealers do more than that.\"},{\"id\":\"pull\",\"label\":\"Pull them\",\"feedback\":\"Many do, and others widen or skew instead.\"},{\"id\":\"all\",\"label\":\"All three, as the risk demands\"}],\"answer\":\"all\"},\"reveal\":\"Dealers widen, skew or pull quotes before news (mechanics; grade B as an observed pattern). A [[quote-skew|skew]] moves both prices to shed inventory: long 400 units, you lower bid and ask so buyers take yours. That's why spreads balloon at releases, as in 2.10.\",\"concept\":\"market-making\"},{\"kind\":\"explain\",\"title\":\"Your limit order is a free option\",\"text\":\"A resting [[limit-order]] is a free option you hand the market: anyone may take it when it suits them. It fills most surely when price comes through it and keeps going, and it misses when price turns just before your level. That's [[adverse-selection]], and why your journal tracks the average move one minute after your passive fills.\"},{\"kind\":\"predict\",\"title\":\"Which day fills you?\",\"prompt\":\"Two days, the same buy limit at 99.90. Day A: the ask falls through 99.90 and on to 99.50. Day B: the ask dips to 99.91, then LABX rallies to 100.40. Which day fills your order?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"Day A\"},{\"id\":\"b\",\"label\":\"Day B\",\"feedback\":\"Day B's ask stopped at 99.91, a cent above your limit. You missed the rally entirely.\"},{\"id\":\"both\",\"label\":\"Both days\",\"feedback\":\"Day B's ask stopped at 99.91, one cent short of your limit.\"}],\"answer\":\"a\"},\"reveal\":\"Day A fills you, and at 99.50 you're 0.40 a unit down. Day B, the one you wanted, never reaches you. Passive orders fill on the moves that continue through them: adverse selection at work.\",\"concept\":\"adverse-selection\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"Today's market makers are often proprietary trading firms using [[high-frequency-trading|high-frequency trading]]. They manage risk across huge numbers of orders, and your 1-lot doesn't interest them on its own. Their quotes respond to flow, inventory and news, not to you.\"},{\"kind\":\"predict\",\"title\":\"Your turn: manage the inventory\",\"prompt\":\"You make the market in LABX at 99.95 / 100.05. Sellers keep hitting your bid: you're now long 400 units, and your limit is ±300. Which quotes next?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"same\",\"label\":\"Keep 99.95 / 100.05\",\"feedback\":\"Unchanged quotes keep attracting the same sellers. Inventory stays above your limit.\"},{\"id\":\"down\",\"label\":\"Skew down: 99.90 / 100.00\"},{\"id\":\"up\",\"label\":\"Skew up: 100.00 / 100.10\",\"feedback\":\"A higher bid attracts more sellers and a higher ask turns buyers away. Inventory grows.\"},{\"id\":\"wide\",\"label\":\"Widen: 99.85 / 100.15\",\"feedback\":\"Wider quotes slow all trading, but don't help you sell the 400 units you hold.\"}],\"answer\":\"down\"},\"reveal\":\"Skewing down makes your ask the cheapest place to buy and your bid less attractive to sellers, so inventory falls back inside ±300. You give up a little price to cut [[inventory-risk]], the third part of a market maker's P&L.\",\"concept\":\"market-making\"}],\"check\":[\"q-3.2.3-1\",\"q-3.2.3-2\",\"q-3.2.3-3\"],\"recap\":{\"takeaways\":[\"Market-making P&L = spread captured − adverse selection ± inventory.\",\"Quotes widen, skew or vanish before news and when inventory builds.\",\"Resting limits fill most surely when price keeps going through them: a free option.\"]}},\"3.2.4\":{\"unit\":\"3.2\",\"courseId\":\"3.2.4\",\"hook\":{\"prompt\":\"You bid 100 units at 100.25. 340 units sit ahead of you. 400 units trade at 100.25. How many do you get?\",\"control\":{\"kind\":\"numeric\",\"unit\":\"units\",\"answer\":60,\"tolerance\":0,\"feedback\":[{\"value\":100,\"text\":\"The first 340 units traded go to the orders ahead of you.\"},{\"value\":0,\"text\":\"400 is 60 more than the 340 ahead of you. Those 60 reach your order.\"},{\"value\":400,\"text\":\"Your order is only 100 units, and 340 of the 400 go to the orders ahead.\"}]},\"compare\":\"You said {yours}. The first 340 units go to the orders ahead of you; the last 60 reach yours, and 40 keep waiting.\",\"concept\":\"queue-priority\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"The queue at 100.25\",\"text\":\"Under [[fifo|FIFO]], price-time priority, orders at one price fill in the order they arrived. Your [[queue-position|queue position]] is the size ahead of you: here 340 of the 900 units bid at 100.25.\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Ahead of you\",\"value\":340,\"role\":\"neutral\"},{\"label\":\"Your order\",\"value\":100,\"role\":\"accent\"},{\"label\":\"Behind you\",\"value\":460,\"role\":\"neutral\"}],\"unit\":\" units\",\"steps\":[\"340 units arrived before you. They fill first.\",\"Your 100 units wait behind them.\",\"460 units arrived later. They wait behind you.\"]},\"concept\":\"queue-priority\"},{\"kind\":\"worked\",\"title\":\"Count the fill\",\"lines\":[\"400 units trade at 100.25.\",\"The first 340 fill the orders ahead of you.\",\"Units that reach you = 400 − 340 = ?\"],\"ask\":{\"answer\":60,\"tolerance\":0,\"unit\":\"units\",\"feedback\":[{\"value\":100,\"text\":\"Only what's left after the 340 ahead of you reaches your order.\"}],\"correct\":\"Right: 60 filled; your other 40 keep waiting, now at the front of the queue.\"},\"concept\":\"queue-priority\"},{\"kind\":\"predict\",\"title\":\"Ask for more\",\"prompt\":\"Before the 400 units trade, you raise your order from 100 to 150 units to catch more. How many do you get now?\",\"control\":{\"kind\":\"numeric\",\"unit\":\"units\",\"answer\":0,\"tolerance\":0,\"feedback\":[{\"value\":60,\"text\":\"Raising the size gives up your place. You go to the back, behind the 460.\"},{\"value\":110,\"text\":\"That assumes you keep your place. A larger order joins the back of the queue.\"}]},\"reveal\":\"A larger order counts as a new one: back of the queue, with 800 units ahead (340 + 460). The same 400 units give you 0. Changing the price, raising the size or changing the account resets priority; cutting the size usually doesn't. Rules differ, so check each venue.\",\"concept\":\"queue-priority\"},{\"kind\":\"worked\",\"title\":\"The same trade under pro-rata\",\"lines\":[\"Under [[pro-rata]] matching, incoming volume is shared in proportion to size, not by time.\",\"Your order is 100 of the 900 units bid at 100.25; 400 trade.\",\"Your share: 400 × 100 ÷ 900 = 44.4.\",\"Rounded down to whole units = ?\"],\"ask\":{\"answer\":44,\"tolerance\":0,\"unit\":\"units\",\"feedback\":[{\"value\":60,\"text\":\"That's FIFO. Pro-rata ignores arrival time and shares by size.\"},{\"value\":45,\"text\":\"Shares are rounded down here; 44.4 becomes 44.\"}],\"correct\":\"Right: 44 units, against 60 under FIFO. Under pro-rata the orders behind you get a share too.\"},\"after\":\"Venues add their own rounding rules and minimum sizes. Pro-rata rewards size, which tempts traders to show more than they really want.\",\"concept\":\"queue-priority\"},{\"kind\":\"match\",\"title\":\"What each rule rewards\",\"prompt\":\"Match each matching rule or feature to what it makes count.\",\"pairs\":[{\"left\":\"FIFO\",\"right\":\"Arriving early\",\"wrong\":\"Price-time priority fills the oldest order at a price first.\"},{\"left\":\"Pro-rata\",\"right\":\"Showing size, even more than you want\",\"wrong\":\"Shares follow size, so traders are tempted to oversize.\"},{\"left\":\"A large tick size\",\"right\":\"Long queues at each price\",\"wrong\":\"Fewer prices to choose from means more orders stack at each one.\"},{\"left\":\"Lead market maker allocation\",\"right\":\"A reserved share for a market maker with obligations\",\"wrong\":\"Some venues set aside part of each fill for a market maker that must quote.\"}],\"columns\":[\"Rule\",\"What counts\"],\"correct\":\"Time under FIFO, size under pro-rata. A coarse [[tick-size|tick size]] makes queues long, so your place in them matters more.\",\"concept\":\"queue-priority\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"On CME, a major futures exchange, most volume matches FIFO; some short-term interest-rate futures use pro-rata or a mix. Stock exchanges mostly use price-time priority. Mechanic, but rules differ by contract: read the venue's matching rules before you rely on a queue.\"},{\"kind\":\"predict\",\"title\":\"Your turn: fill without crossing\",\"prompt\":\"You want 100 units at 100.25 without crossing the spread. 300 units are bid there now, and more join every second. About 450 units will trade at 100.25 before the level clears. Your move?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"now\",\"label\":\"Join now with 100 units\"},{\"id\":\"wait\",\"label\":\"Wait for the queue to shorten, then join\",\"feedback\":\"Every order that joins before you stands ahead of you. Waiting moves you back, not forward.\"},{\"id\":\"big\",\"label\":\"Join now with 200 units, to fill faster\",\"feedback\":\"Under FIFO size doesn't speed you up, and you might buy 150 units, more than you wanted.\"},{\"id\":\"raise\",\"label\":\"Join with 100, raise to 150 when selling starts\",\"feedback\":\"Raising the size resets your priority: you'd join the back, behind everyone who came after you.\"}],\"answer\":\"now\"},\"reveal\":\"Join now at the size you want: 300 ahead, 450 traded, so your 100 fill with 50 to spare. Under FIFO, time is your only lever, so don't amend upward.\",\"concept\":\"queue-priority\"}],\"check\":[\"q-3.2.4-1\",\"q-3.2.4-2\",\"q-3.2.4-3\"],\"recap\":{\"takeaways\":[\"Under FIFO, you fill only after the size ahead of you trades.\",\"Raising size, changing price or account sends you to the back of the queue.\",\"Pro-rata shares volume by size: 400 × 100 ÷ 900 gives 44 units.\"]}},\"3.2.5\":{\"unit\":\"3.2\",\"courseId\":\"3.2.5\",\"hook\":{\"prompt\":\"The book shows 50 units at 100.00. 600 units trade there, and 50 are still showing. How?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"spoof\",\"label\":\"Spoofing\",\"feedback\":\"Spoofed orders vanish before they fill. This size kept filling: 600 units traded.\"},{\"id\":\"iceberg\",\"label\":\"An iceberg order\"},{\"id\":\"error\",\"label\":\"A data error\",\"feedback\":\"Possible, but this pattern has a common, legal explanation.\"},{\"id\":\"hidden\",\"label\":\"A hidden market maker\",\"feedback\":\"Hidden size can trade there too, but the displayed 50 kept coming back after each fill.\"}],\"answer\":\"iceberg\"},\"compare\":\"You said {yours}. An iceberg showed 50 at a time and refilled from a hidden reserve: 600 traded and 50 were still on show.\",\"concept\":\"iceberg-order\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"What the book doesn't show\",\"text\":\"An [[iceberg-order]] shows only a [[display-quantity|display quantity]] and keeps the rest in reserve. Each time the slice fills, a new one appears, at the back of the queue. This one had 800 units: after the 600, 200 remain.\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Displayed\",\"value\":50,\"role\":\"accent\"},{\"label\":\"Hidden reserve\",\"value\":750,\"role\":\"neutral\"}],\"unit\":\" units\",\"steps\":[\"The book shows 50 units at 100.00.\",\"Behind them sit 750 more that nobody sees. 600 trade in 12 slices of 50.\"]},\"concept\":\"hidden-liquidity\"},{\"kind\":\"match\",\"title\":\"Every order type gives something up\",\"prompt\":\"Match each order type to its trade-off: iceberg, [[hidden-order|hidden]], [[midpoint-peg|midpoint peg]] and [[post-only]].\",\"pairs\":[{\"left\":\"Iceberg\",\"right\":\"Hides size, but each refill loses priority\",\"wrong\":\"An iceberg shows a slice and refills it; each refill joins the back of the queue.\"},{\"left\":\"Hidden order\",\"right\":\"Invisible, but displayed orders at its price fill first\",\"wrong\":\"A hidden order shows nothing, and most venues fill displayed orders at the same price first.\"},{\"left\":\"Midpoint peg\",\"right\":\"Better price, lower chance of a fill\",\"wrong\":\"A midpoint peg sits halfway between bid and ask: a better price, but it fills only if someone meets it there.\"},{\"left\":\"Post-only\",\"right\":\"Always adds liquidity, but can be rejected\",\"wrong\":\"A post-only order must rest. If it would take liquidity, it's rejected or repriced.\"}],\"columns\":[\"Order type\",\"Trade-off\"],\"correct\":\"No order type is free: each one trades visibility, priority, price or the certainty of a fill.\",\"concept\":\"hidden-liquidity\"},{\"kind\":\"worked\",\"title\":\"Fees on a round trip\",\"lines\":[\"A [[maker-taker]] venue pays makers 0.002 a unit and charges takers 0.003.\",\"Round trip of 1,000 units: you buy with a resting limit, then sell with a market order.\",\"Entry as maker: +2.00. Exit as taker: −3.00.\",\"Net fees = ?\"],\"ask\":{\"answer\":-1,\"tolerance\":0.005,\"unit\":\"vUSD\",\"feedback\":[{\"value\":1,\"text\":\"The exit took liquidity: it pays 3.00, more than the entry's 2.00 rebate. The net is negative.\"},{\"value\":5,\"text\":\"The rebate and the fee have opposite signs: +2.00 − 3.00.\"},{\"value\":-6,\"text\":\"That's two taker fills. Your entry rested, so it earned the rebate.\"}],\"correct\":\"Right: −1.00.\"},\"after\":\"Both legs as market orders: −6.00. Both resting: +4.00, but only if both fill, and a resting exit may never fill.\",\"concept\":\"maker-taker\"},{\"kind\":\"explain\",\"title\":\"Layers: legal or not\",\"text\":\"Resting genuine orders at several prices is legal: they're there to trade. The line is intent. Orders placed to be cancelled before they can fill, to make others believe in supply or demand that isn't there, are spoofing, and illegal. Hidden size is real liquidity you can't see; displayed size can be liquidity that isn't there.\"},{\"kind\":\"predict\",\"title\":\"Native or synthetic?\",\"prompt\":\"A native iceberg is held by the exchange. A synthetic one is run by your platform, which sends a new order after each fill. Which one leaves a gap with nothing showing between slices?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"native\",\"label\":\"The native iceberg\",\"feedback\":\"The exchange holds a native iceberg's reserve and refills the slice itself, at once.\"},{\"id\":\"synthetic\",\"label\":\"The synthetic iceberg\"},{\"id\":\"neither\",\"label\":\"Neither\",\"feedback\":\"A synthetic iceberg waits for the fill report, then sends a new order: a short gap.\"}],\"answer\":\"synthetic\"},\"reveal\":\"A synthetic iceberg lives on your platform: after each fill it sends a brand-new order, so there's a gap, and the exchange sees only separate small orders. A native one is known to the exchange, which refills at once. Either way each refill joins the back of the queue. Rules for hidden size differ by venue.\",\"concept\":\"iceberg-order\"},{\"kind\":\"worked\",\"title\":\"Your turn: build the iceberg\",\"lines\":[\"You want 1,000 units at 99.95, resting below the 100.05 ask, showing no more than 100 at a time.\",\"Iceberg buy: total 1,000, display quantity 100.\",\"The first slice goes up when you place the order; each later slice is a refill.\",\"Refills until the order is done = ?\"],\"ask\":{\"answer\":9,\"tolerance\":0,\"unit\":\"refills\",\"feedback\":[{\"value\":10,\"text\":\"1,000 ÷ 100 = 10 slices, but the first one goes up when you place the order. Refills: 9.\"},{\"value\":900,\"text\":\"That's the size in reserve. Count slices of 100, not units.\"}],\"correct\":\"Right: 10 slices, 9 refills.\"},\"after\":\"Each of the 9 refills joins the back of the queue at 99.95. Showing less hides your size, but you pay for it in priority every time.\",\"concept\":\"iceberg-order\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"Every order type gives something away: visibility, priority, price or the certainty of a fill. Decide which one you can afford to lose before you choose the order.\"}],\"check\":[\"q-3.2.5-1\",\"q-3.2.5-2\",\"q-3.2.5-3\"],\"recap\":{\"takeaways\":[\"Icebergs, hidden, pegged and post-only orders each trade visibility, priority, price or fill certainty.\",\"Native icebergs refill at the exchange; synthetic ones resend from your platform. Both lose priority.\",\"Maker-taker, passive in and aggressive out on 1,000 units: +2.00 − 3.00 = −1.00.\"]}},\"3.2.6\":{\"unit\":\"3.2\",\"courseId\":\"3.2.6\",\"hook\":{\"prompt\":\"Your broker is the counterparty to your trades. Does that mean it hunts your stops?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"yes\",\"label\":\"Yes\",\"feedback\":\"The conflict is real, but a chart can't show intent, and no evidence shows B-books hunting stops.\"},{\"id\":\"no\",\"label\":\"No\",\"feedback\":\"Nobody can promise that either. The conflict exists; what you can check is your execution data.\"},{\"id\":\"cant\",\"label\":\"You can't tell from a chart\"}],\"answer\":\"cant\"},\"compare\":\"You said {yours}. A B-book gains when you lose: a real, structural conflict that regulation manages. 'B-books hunt stops' has no evidence behind it (grade D); your fills and rejects are what you can check.\",\"concept\":\"broker-models\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"Follow your order\",\"text\":\"Where does your order go after you press Buy? Pick a path; the list below then shows all four models.\",\"figure\":{\"kind\":\"flow\",\"start\":\"n1\",\"interactive\":true,\"nodes\":[{\"id\":\"n1\",\"text\":\"Does the broker take the other side itself?\",\"kind\":\"question\",\"yes\":\"n2\",\"no\":\"n3\"},{\"id\":\"n2\",\"text\":\"Does it pass some clients' orders on, such as consistent winners?\",\"kind\":\"question\",\"yes\":\"hybrid\",\"no\":\"bbook\"},{\"id\":\"n3\",\"text\":\"Does your order meet many participants' orders in one book?\",\"kind\":\"question\",\"yes\":\"ecn\",\"no\":\"stp\"},{\"id\":\"bbook\",\"text\":\"B-book: the broker is your counterparty\",\"kind\":\"end\"},{\"id\":\"hybrid\",\"text\":\"Hybrid: B-book for most clients, A-book for some\",\"kind\":\"end\"},{\"id\":\"ecn\",\"text\":\"ECN: one book shared by many participants\",\"kind\":\"end\"},{\"id\":\"stp\",\"text\":\"Agency/STP: passed to outside liquidity providers\",\"kind\":\"end\"}],\"steps\":[\"[[stp|Agency/STP]]: orders go on to outside liquidity providers; the broker earns a commission or markup.\",\"[[ecn|ECN]]: your order joins one book with many participants, often with partial fills.\",\"[[b-book|B-book]]: the broker takes the other side, so your loss is its gain.\",\"Hybrid: most clients B-booked, some passed on ([[a-book|A-book]]). How firms choose is rarely disclosed.\"]},\"concept\":\"broker-models\"},{\"kind\":\"match\",\"title\":\"Read the client agreement\",\"prompt\":\"Match each clause to the broker model it reveals.\",\"pairs\":[{\"left\":\"'We act as principal to all your trades.'\",\"right\":\"B-book\",\"wrong\":\"Principal means the broker itself is the other side of your trade.\"},{\"left\":\"'We pass your orders to liquidity providers and charge a commission.'\",\"right\":\"Agency/STP\",\"wrong\":\"Passing orders on for a commission is the agency model.\"},{\"left\":\"'Your order is matched against other participants' orders in our network.'\",\"right\":\"ECN\",\"wrong\":\"Matching many participants in one book is what an ECN does.\"},{\"left\":\"'Requotes may occur in fast markets.'\",\"right\":\"A dealer quoting its own prices\",\"wrong\":\"A [[requote]] means the broker sets prices itself and may decline yours: a dealer.\"}],\"columns\":[\"Clause\",\"Model\"],\"correct\":\"The agreement tells you who is on the other side. 'Principal' and 'requotes' point to a dealer; 'commission' and 'liquidity providers' to agency.\",\"concept\":\"broker-models\"},{\"kind\":\"explain\",\"title\":\"How regulation manages the conflict\",\"text\":\"Regulation manages the B-book conflict rather than banning it. Since 2018, EU retail CFD clients get leverage caps from 30:1 on major FX pairs down to 2:1 on crypto, a [[margin-close-out]] at 50% of margin, [[negative-balance-protection]] and a warning with the share of accounts that lose, 74–89% when ESMA reviewed it. Grade: Mechanic.\"},{\"kind\":\"figure\",\"title\":\"A last-look report\",\"text\":\"With [[last-look|last look]], a liquidity provider may reject your request at its quoted price within a short window, 50–200 ms in the simulator. Here are 120 requests, sorted by which way price moved during the window.\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Moved your way: filled\",\"value\":45,\"role\":\"neutral\"},{\"label\":\"Moved your way: rejected\",\"value\":18,\"role\":\"down\"},{\"label\":\"Moved the dealer's way: filled\",\"value\":57,\"role\":\"neutral\"},{\"label\":\"Moved the dealer's way: rejected\",\"value\":0,\"role\":\"down\"}],\"unit\":\" requests\",\"steps\":[\"When price moved your way, 18 of 63 requests were rejected.\",\"When it moved the dealer's way, all 57 filled. The rejects are one-sided.\"]},\"concept\":\"last-look\"},{\"kind\":\"predict\",\"title\":\"Read the slippage\",\"prompt\":\"Your execution report: 120 market orders. 83 filled at the quoted price, 37 filled worse, none filled better. What does it show?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"noise\",\"label\":\"Normal market noise\",\"feedback\":\"Noise moves both ways. With no fill better than quoted, this is one-sided.\"},{\"id\":\"flag\",\"label\":\"Only negative slippage is passed on: a red flag\"},{\"id\":\"hunt\",\"label\":\"Proof the broker hunts stops\",\"feedback\":\"It shows one-sided slippage, a cost worth challenging. It says nothing about stops or intent.\"},{\"id\":\"fast\",\"label\":\"You trade too fast\",\"feedback\":\"Speed can raise slippage, but it would still go both ways. None better is the tell.\"}],\"answer\":\"flag\"},\"reveal\":\"During any delay price moves both ways, so a fair process gives some fills a better price. 37 worse and 0 better means gains are kept and losses passed on. Ask the broker for its slippage and last-look policy, and compare with another account.\",\"concept\":\"last-look\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"The FX Global Code, principle 17 (revised December 2017), says a liquidity provider shouldn't trade on the information in your request during the last-look window. The code is voluntary: firms sign up to it. Its 2021 review kept the principle.\"},{\"kind\":\"worked\",\"title\":\"Your turn: the all-in cost\",\"lines\":[\"The same 30 scalps of 100 units on three simulated accounts. Cost per round trip:\",\"STP: spread 3.00 + commission 7.00 = 10.00. B-book: spread 12.00 + slippage 2.00 = 14.00. ECN: spread 2.00 + commission 6.00 = 8.00.\",\"For 30 trades: STP 300.00, B-book 420.00, ECN = ?\"],\"ask\":{\"answer\":240,\"tolerance\":0,\"unit\":\"vUSD\",\"feedback\":[{\"value\":8,\"text\":\"That's one round trip. The strategy made 30.\"},{\"value\":180,\"text\":\"That's the ECN's commissions only. Add the spread.\"}],\"correct\":\"Right: 240.00, the lowest of the three.\"},\"after\":\"What each broker earned: the STP broker its commissions, 210.00; the ECN 180.00; the B-book keeps the 420.00 and also gains whatever you lose on price. The ECN filled some orders only partly, so cheapest isn't the whole story.\",\"concept\":\"broker-models\"}],\"check\":[\"q-3.2.6-1\",\"q-3.2.6-2\",\"q-3.2.6-3\"],\"recap\":{\"takeaways\":[\"STP passes orders on, ECN shares one book, B-book takes the other side; hybrids mix.\",\"A B-book gains when you lose; leverage caps and loss limits manage that conflict.\",\"Slippage that only goes against you, or one-sided rejects, is a red flag.\"]}},\"3.2.7\":{\"unit\":\"3.2\",\"courseId\":\"3.2.7\",\"hook\":{\"prompt\":\"Your broker charges zero commission. Is your trade free?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"yes\",\"label\":\"Yes\",\"feedback\":\"Someone pays the broker. The cost moves into the price you get, the routing and payments for your order flow.\"},{\"id\":\"moved\",\"label\":\"No: the cost moved somewhere else\"},{\"id\":\"limit\",\"label\":\"Only with limit orders\",\"feedback\":\"Limit orders save the spread, but the routing and the payment for your flow stay the same.\"}],\"answer\":\"moved\"},\"compare\":\"You said {yours}. The cost moves into the price you get, the routing and the payment for your order flow. Only execution quality shows how much.\",\"concept\":\"payment-for-order-flow\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"One best price from many venues\",\"text\":\"A US stock quotes on many exchanges at once, and each one shows only its own quotes. The [[nbbo|NBBO]] stitches them together: the highest bid and the lowest offer among them. Brokers measure fills against it.\"},{\"kind\":\"hotspot\",\"title\":\"Find the NBBO\",\"prompt\":\"Three exchanges quote the same stock. Tap the NBBO bid.\",\"chart\":{\"candles\":[{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03},{\"o\":100.03,\"h\":100.03,\"l\":100.03,\"c\":100.03}],\"hideCandles\":true,\"range\":[99.92,100.14],\"height\":300,\"layers\":[{\"kind\":\"level\",\"price\":100.1,\"role\":\"resistance\",\"label\":\"X ASK 100.10\",\"chip\":false},{\"kind\":\"level\",\"price\":100.08,\"role\":\"resistance\",\"label\":\"Y ASK 100.08\",\"chip\":false},{\"kind\":\"level\",\"price\":100.06,\"role\":\"resistance\",\"label\":\"Z ASK 100.06\",\"chip\":false},{\"kind\":\"level\",\"price\":100,\"role\":\"support\",\"label\":\"Y BID 100.00\",\"chip\":false},{\"kind\":\"level\",\"price\":99.98,\"role\":\"support\",\"label\":\"Z BID 99.98\",\"chip\":false},{\"kind\":\"level\",\"price\":99.96,\"role\":\"support\",\"label\":\"X BID 99.96\",\"chip\":false}],\"describe\":\"Three exchanges quote one stock. X: bid 99.96, ask 100.10. Y: bid 100.00, ask 100.08. Z: bid 99.98, ask 100.06.\"},\"zones\":[{\"id\":\"x-ask\",\"label\":\"X ask 100.10\",\"price\":100.1,\"feedback\":\"That's an ask, and the highest one: the worst place to buy.\"},{\"id\":\"y-ask\",\"label\":\"Y ask 100.08\",\"price\":100.08,\"feedback\":\"That's an ask, where you'd buy. The NBBO bid is on the bid side.\"},{\"id\":\"z-ask\",\"label\":\"Z ask 100.06\",\"price\":100.06,\"feedback\":\"That's the NBBO ask, the lowest offer. Now find the best bid.\"},{\"id\":\"y-bid\",\"label\":\"Y bid 100.00\",\"price\":100},{\"id\":\"z-bid\",\"label\":\"Z bid 99.98\",\"price\":99.98,\"feedback\":\"A bid, but Y bids more: 100.00.\"},{\"id\":\"x-bid\",\"label\":\"X bid 99.96\",\"price\":99.96,\"feedback\":\"The lowest bid of the three. The NBBO takes the highest.\"}],\"answer\":\"y-bid\",\"correct\":\"Right: 100.00 on Y. With Z's 100.06 ask, the NBBO is 100.00 / 100.06: 0.06 wide, tighter than any single exchange's 0.08 or 0.14.\",\"concept\":\"nbbo\"},{\"kind\":\"explain\",\"title\":\"Fast feeds and stale quotes\",\"text\":\"The NBBO comes from the [[sip|SIP]], the consolidated feed. Firms that buy each exchange's direct feed see changes a little sooner, so the quote on your screen can already be gone: a stale quote. Speed matters most to those who trade on tiny price changes. Grade: Mechanic.\"},{\"kind\":\"predict\",\"title\":\"Who pays the broker?\",\"prompt\":\"Your zero-commission broker sends your market order on. Who pays the broker for it?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"nobody\",\"label\":\"Nobody: it runs at a loss\",\"feedback\":\"Brokers are paid for the flow, and also earn on cash balances and lending.\"},{\"id\":\"filler\",\"label\":\"The firm that fills your order\"},{\"id\":\"exchange\",\"label\":\"The exchange, on every order\",\"feedback\":\"Some exchanges pay rebates, but most US retail market orders never reach an exchange.\"},{\"id\":\"clients\",\"label\":\"Other clients\",\"feedback\":\"Your order flow itself is what's being paid for.\"}],\"answer\":\"filler\"},\"figure\":{\"kind\":\"flow\",\"start\":\"order\",\"nodes\":[{\"id\":\"order\",\"text\":\"Your market order\",\"kind\":\"pause\",\"next\":\"broker\"},{\"id\":\"broker\",\"text\":\"Your broker: zero commission\",\"kind\":\"pause\",\"next\":\"wholesaler\"},{\"id\":\"wholesaler\",\"text\":\"Wholesaler: fills it from its own book, often slightly inside the NBBO\",\"kind\":\"pause\",\"next\":\"pays\"},{\"id\":\"pays\",\"text\":\"The wholesaler pays your broker for the flow\",\"kind\":\"end\"}]},\"reveal\":\"Most US retail market orders go to a [[wholesaler]] that [[internalisation|internalises]] them and pays the broker: [[payment-for-order-flow]]. Fills often come with [[price-improvement]] inside the NBBO, and the wholesaler profits because retail flow is, on average, less informed. Whether PFOF helps or hurts retail traders overall is contested: grade C.\",\"concept\":\"payment-for-order-flow\"},{\"kind\":\"worked\",\"title\":\"Price improvement\",\"lines\":[\"NBBO: 100.00 / 100.06. You buy 200 units.\",\"The wholesaler fills you at 100.05, one cent inside the best ask.\",\"Price improvement = 0.01 × 200 = ?\"],\"ask\":{\"answer\":2,\"tolerance\":0.005,\"unit\":\"vUSD\",\"feedback\":[{\"value\":0.01,\"text\":\"That's per unit. Multiply by the 200 units.\"}],\"correct\":\"Right: 2.00 vUSD better than the NBBO.\"},\"after\":\"In this synthetic case the wholesaler paid your broker 0.002 × 200 = 0.40 for the order. You see the 2.00 improvement; the 0.40 appears only in the broker's routing reports.\",\"concept\":\"best-execution\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"[[best-execution|Best execution]] is a duty, not a promise of the best price. In the US it needs reasonable diligence and a regular, rigorous review, at least quarterly (FINRA 5310). PFOF isn't a violation in itself, but can't compromise best execution, and disclosing it isn't enough. The EU has banned PFOF, with exemptions only until 30 June 2026.\"},{\"kind\":\"worked\",\"title\":\"Your turn: compare two brokers\",\"lines\":[\"Two brokers each filled 20 of your market orders of 200 units: 4,000 units in all.\",\"Broker A: zero commission; price improvement 0.002 a unit, 8.00. Fill rate 100%, median 0.05 s.\",\"Broker B: 1.00 per order, 20.00 in all; improvement 0.009 a unit, 36.00. Fill rate 100%, median 0.08 s.\",\"Broker B, net of commission = ?\"],\"ask\":{\"answer\":16,\"tolerance\":0.005,\"unit\":\"vUSD\",\"feedback\":[{\"value\":36,\"text\":\"That's B's improvement before its commission. Subtract the 20.00.\"},{\"value\":8,\"text\":\"That's broker A. Work out B: 36.00 − 20.00.\"}],\"correct\":\"Right: 16.00, twice broker A's 8.00.\"},\"after\":\"Zero commission was the more expensive route here. Both filled every order, and the speed gap is tiny for an order this size: net price decides.\",\"concept\":\"best-execution\"}],\"check\":[\"q-3.2.7-1\",\"q-3.2.7-2\",\"q-3.2.7-3\"],\"recap\":{\"takeaways\":[\"NBBO: the highest bid and lowest offer across exchanges; direct feeds see it sooner.\",\"Zero commission moves the cost into routing and PFOF; best execution is a duty, not a guarantee.\",\"Compare brokers net: price improvement minus commission, with fill rate and speed beside it.\"]}},\"3.2.8\":{\"unit\":\"3.2\",\"courseId\":\"3.2.8\",\"hook\":{\"prompt\":\"In a call auction everyone trades at one price. Which one?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"high\",\"label\":\"The highest bid\",\"feedback\":\"The highest bidder would trade almost alone. The auction looks for the price where the most units can trade.\"},{\"id\":\"last\",\"label\":\"The last trade\",\"feedback\":\"The auction ignores the last trade. It sets a new price from the orders it collected.\"},{\"id\":\"volume\",\"label\":\"The price where the most volume can trade\"},{\"id\":\"avg\",\"label\":\"The average of all orders\",\"feedback\":\"An average ignores size and side. The price is where most units match.\"}],\"answer\":\"volume\"},\"compare\":\"You said {yours}. The auction picks the price where the most units can trade: the uncross price.\",\"concept\":\"call-auction\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"Demand meets supply\",\"text\":\"In a [[call-auction|call auction]], orders collect without trading. At each price, count the buyers willing to pay at least that much and the sellers willing to take that little. The auction [[uncross|uncrosses]] where the most units can change hands.\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Buy at 99.90 or more\",\"value\":1300,\"role\":\"up\"},{\"label\":\"Buy at 100.00 or more\",\"value\":1300,\"role\":\"up\"},{\"label\":\"Buy at 100.10 or more\",\"value\":1000,\"role\":\"up\"},{\"label\":\"Buy at 100.20 or more\",\"value\":600,\"role\":\"up\"},{\"label\":\"Buy at 100.30 or more\",\"value\":400,\"role\":\"up\"},{\"label\":\"Sell at 99.90 or less\",\"value\":300,\"role\":\"down\"},{\"label\":\"Sell at 100.00 or less\",\"value\":600,\"role\":\"down\"},{\"label\":\"Sell at 100.10 or less\",\"value\":900,\"role\":\"down\"},{\"label\":\"Sell at 100.20 or less\",\"value\":1300,\"role\":\"down\"},{\"label\":\"Sell at 100.30 or less\",\"value\":1500,\"role\":\"down\"}],\"unit\":\" units\",\"steps\":[\"Demand falls as the price rises: 1,300 units at 99.90, 400 at 100.30.\",\"Supply rises with the price: 300 at 99.90, 1,500 at 100.30. They cross near 100.10.\"]},\"concept\":\"call-auction\"},{\"kind\":\"worked\",\"title\":\"Find the uncross\",\"lines\":[\"Buys: 100 at market, 300 at 100.30, 200 at 100.20, 400 at 100.10, 300 at 100.00.\",\"Sells: 100 at market, 200 at 99.90, 300 at 100.00, 300 at 100.10, 400 at 100.20, 200 at 100.30.\",\"Volume that can trade, the smaller side: 99.90: 300 · 100.00: 600 · 100.10: 900 · 100.20: 600 · 100.30: 400.\",\"Uncross price = ?\"],\"ask\":{\"answer\":100.1,\"tolerance\":0.001,\"unit\":\"vUSD\",\"feedback\":[{\"value\":100.3,\"text\":\"That's the highest buy limit. Only 400 units can trade there.\"},{\"value\":100,\"text\":\"600 units can trade at 100.00, but 900 can at 100.10.\"},{\"value\":100.2,\"text\":\"Only 600 units can trade at 100.20; sellers outnumber buyers there.\"}],\"correct\":\"Right: 100.10, where 900 units trade.\"},\"after\":\"At 100.10 buyers want 1,000 and sellers offer 900: an [[auction-imbalance|imbalance]] of 100 units to buy. 100 of the 400 bid at 100.10 stay unfilled.\",\"concept\":\"call-auction\"},{\"kind\":\"explain\",\"title\":\"What the auction tells you\",\"text\":\"Before the cross, exchanges publish the [[indicative-price|indicative price]], the [[paired-volume|paired volume]] and the side and size of the imbalance. Nasdaq starts its opening messages at 09:25 for a 09:30 cross, and its closing messages at 15:50 for 16:00. The LSE ends its auctions at a random moment within 30 seconds, to discourage last-second games.\"},{\"kind\":\"predict\",\"title\":\"Offset the imbalance\",\"prompt\":\"Same book: indicative 100.10, paired 900, imbalance 100 to buy. You add a sell limit of 100 units at 100.10. What changes?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"down\",\"label\":\"The price falls to 100.00\",\"feedback\":\"At 100.00 only 600 units could trade. 100.10 still pairs the most: now 1,000.\"},{\"id\":\"fill\",\"label\":\"1,000 units trade at 100.10, with no imbalance\"},{\"id\":\"nothing\",\"label\":\"Nothing: the price is already set\",\"feedback\":\"Nothing is set until the cross. Every order in the call period counts.\"},{\"id\":\"up\",\"label\":\"The price rises to 100.20\",\"feedback\":\"More selling can't push the price up. 100.10 now pairs 1,000 units.\"}],\"answer\":\"fill\"},\"reveal\":\"Your 100 units meet the 100 buyers left over: 1,000 trade at 100.10, with no imbalance. Selling against a buy imbalance, at the indicative price or better, is how liquidity providers use auctions. A buy of 100 at market would do the opposite: leave 200 units unfilled.\",\"concept\":\"auction-imbalance\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"The close matters: index funds trade at the closing price, so the closing auction carries a large share of the day's volume. On a thin instrument, a [[market-on-close]] or market-on-open order can fill at a surprising price. A halted market reopens through an auction too, and stops can trigger at the reopening price, far from their levels.\"},{\"kind\":\"predict\",\"title\":\"Your turn: the closing auction\",\"prompt\":\"A stock's closing auction shows: indicative price 50.40, paired volume 1,400, imbalance 300 to sell. You want to buy 300 and help the auction. Which order reduces the imbalance without moving the price?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"buy40\",\"label\":\"Buy 300, limit 50.40\"},{\"id\":\"buy30\",\"label\":\"Buy 300, limit 50.30\",\"feedback\":\"A buy limit below the indicative price doesn't take part at 50.40. The imbalance stays 300.\"},{\"id\":\"sellmkt\",\"label\":\"Sell 300 at market\",\"feedback\":\"That adds to the sell side: the price drops to 50.30 and the imbalance flips to 500 to buy.\"}],\"answer\":\"buy40\"},\"reveal\":\"Your buy at 50.40 meets the 300 sellers left over. A limit at the indicative price, or better, takes part without pushing the price; one below it doesn't trade at all.\",\"concept\":\"auction-imbalance\"},{\"kind\":\"worked\",\"title\":\"Your turn: predict the cross\",\"lines\":[\"With your buy, demand at 50.40 is 1,400 + 300 = 1,700; supply there is 1,700.\",\"At 50.30: demand 2,300, supply 1,200, so 1,200 trade. At 50.50: demand 900, supply 2,000, so 900.\",\"Units that trade at the uncross = ?\"],\"ask\":{\"answer\":1700,\"tolerance\":0,\"unit\":\"units\",\"feedback\":[{\"value\":1400,\"text\":\"That was before your order. Add your 300 to demand at 50.40.\"},{\"value\":1200,\"text\":\"That's at 50.30. At 50.40 more units can match.\"}],\"correct\":\"Right: 1,700 units at 50.40.\"},\"after\":\"The uncross stays at 50.40 with no imbalance, and your 300 fill at the price the auction was already showing.\",\"concept\":\"call-auction\"}],\"check\":[\"q-3.2.8-1\",\"q-3.2.8-2\",\"q-3.2.8-3\"],\"recap\":{\"takeaways\":[\"The uncross price is where the most volume can trade: 900 units at 100.10.\",\"Offset an imbalance with a limit at the indicative price or better; don't add to it.\",\"Index funds trade the close; halted markets reopen by auction, and stops fill at that price.\"]}}}");
